from typing import Any, Literal, Annotated
from pydantic import BaseModel
from fastapi import FastAPI, Body
from fastapi.params import Tag, Discriminator
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

