    # This should be a body parameter. If it's treated as a query parameter, 
    # sending it in the body will result in a 422 Unprocessable Entity 
    # because the query parameter 'dessert' is missing.
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 10, "num_ingredients": 3})
    print(f"Status code: {response.status_code}")
    print(f"Response: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_dessert()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
